// internal/restful/v2/entity.go line 120-165
func (h *EntityHandler) Upsert(ctx context.Context, req *restful.UpsertReq) (*restful.UpsertResp, error) {
    // Raw data parsing - no type validation at REST layer
    rawData := req.Data
    if len(rawData) == 0 {
        return nil, errors.New("data is empty")
    }
    // Direct pass-through to protobuf without JSON field schema validation
    m.InsertOrUpsert(ctx, collectionName, partitionName, rawData)
    return &restful.UpsertResp{UpsertCount: int64(len(rawData))}, nil
}
